/**
 * Canvas fixtures: the shared stories, run in the browser on the in-memory repositories the domain spec binds.
 * `load(story, scenario)` empties every repository and replays that scenario's Givens, so a canvas screen draws
 * what the story set up. Generated by the LERN claude_design format; placeholders are filled at build time.
 */
import { installStoryHost, withStory } from '__STORY_TEST__/story-test';
import { domainRepositories } from '__STORY_TEST__/repositories';
__IMPORTS__
__EXAMPLES__
__SEED_PASTES__
__RESETTABLE_IMPORTS__

type Step = () => void | Promise<void>;
type Frame = { name: string; beforeEach: Step[] };

const STORIES: string[] = __STORIES__;
/** Other state the stories' runtime resets between tests (gateways, clocks): reset with the repositories. */
const RESETTABLES: unknown[] = [__RESETTABLES__];
const EACH_BACKGROUND = 'Background (each scenario)';
const frames: Frame[] = [];
const givens = new Map<string, Step[]>();
const scenariosByStory = new Map<string, string[]>();

function key(story: string, scenario: string): string {
  return `${story}::${scenario}`;
}

function record(): void {
  if (frames.length < 2) return;
  const story = frames[0].name;
  const scenario = frames[frames.length - 1].name;
  if (scenario === EACH_BACKGROUND || givens.has(key(story, scenario))) return;
  givens.set(key(story, scenario), frames.flatMap(frame => frame.beforeEach));
  scenariosByStory.set(story, [...(scenariosByStory.get(story) ?? []), scenario]);
}

/** A host that runs nothing: it records, for each scenario, the Givens a test would run before its Then. */
installStoryHost({
  describe(name, build) {
    frames.push({ name, beforeEach: [] });
    try {
      build();
    } finally {
      frames.pop();
    }
  },
  it() {
    record();
  },
  beforeEach(step) {
    frames[frames.length - 1]?.beforeEach.push(step);
  },
  beforeAll() {},
  afterAll() {},
});

for (const story of STORIES) {
  try {
    withStory(story, domainRepositories()).run();
  } catch (problem) {
    console.warn(`Canvas fixtures: story "${story}" not loaded`, problem);
  }
}

export function stories(): string[] {
  return [...scenariosByStory.keys()];
}

export function scenarios(story: string): string[] {
  return scenariosByStory.get(story) ?? [];
}

/** The stories' example fixtures, by export name: the data a scenario's steps enter, show and seed. */
export const examples: Record<string, unknown> = Object.assign({}, __EXAMPLE_MODULES__);

type SeedField = { label: string; value: string; submit?: boolean };

/** What dev mode's "Paste seed data" types on the screen at *path*: each field by the label it shows, from the examples. */
export function pasteFor(path: string): { title: string; fields: SeedField[] } | null {
  const trim = (value: string) => (value.length > 1 ? value.replace(/\/$/, '') : value);
  const pastes = seedPastes() as Array<{ path: string; title: string; fields: SeedField[] }>;
  const found = pastes.find(paste => trim(paste.path) === trim(path))
    ?? pastes.find(paste => paste.path.endsWith('/') && trim(path).startsWith(paste.path))
    ?? null;
  if (!found) return null;
  const unique = String(Date.now() % 100000);
  return { title: found.title, fields: found.fields.map(field => ({ ...field, value: String(field.value).replace('{unique}', unique) })) };
}

export function repositories(): ReturnType<typeof domainRepositories> {
  return domainRepositories();
}

/** Empty every repository, then run the scenario's Givens. Returns the repositories they filled. */
export async function load(story: string, scenario: string): Promise<ReturnType<typeof domainRepositories>> {
  const steps = givens.get(key(story, scenario));
  if (!steps) throw new Error(`Canvas fixtures: no scenario "${scenario}" in story "${story}"`);
  for (const repository of Object.values(domainRepositories()) as Array<{ _reset?: () => void }>) repository._reset?.();
  for (const held of RESETTABLES as Array<{ _reset?: () => void }>) held._reset?.();
  for (const step of steps) await step();
  return domainRepositories();
}
